import React, { useState } from 'react';
// Import icons for the contact cards
import { FaEnvelope, FaPhoneAlt } from 'react-icons/fa';

// --- STYLES ---
const styles = {
  contactSection: {
    backgroundColor: '#1a202c',
    padding: '80px 24px',
    fontFamily: 'sans-serif',
    color: '#e2e8f0',
    borderTop: '1px solid #2d3748',
  },
  // Main container for the two-column layout
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    gap: '64px', // Space between the two columns
    flexWrap: 'wrap', // Allows columns to stack on smaller screens
  },
  // Left column for info
  infoColumn: {
    flex: 1,
    minWidth: '300px',
  },
  // Right column for the form
  formColumn: {
    flex: 1,
    minWidth: '300px',
  },
  title: {
    fontSize: '2.8rem',
    fontWeight: 'bold',
    color: '#ffffff',
    marginBottom: '16px',
    lineHeight: '1.2',
  },
  subtitle: {
    fontSize: '1.1rem',
    color: '#a0aec0',
    marginBottom: '48px',
  },
  // Container for the info cards
  cardsContainer: {
    display: 'flex',
    flexDirection: 'column',
    gap: '20px',
  },
  // Style for the clickable contact cards
  card: {
    backgroundColor: '#2d3748',
    border: '1px solid #4a5568',
    borderRadius: '12px',
    padding: '24px',
    display: 'flex',
    alignItems: 'center',
    textDecoration: 'none', // Removes underline from the link
    color: 'inherit', // Inherits the color from parent
    transition: 'background-color 0.3s ease, border-color 0.3s ease',
  },
  iconWrapper: {
    color: '#a7ffeb', // Mint-teal icon color
    marginRight: '20px',
    fontSize: '1.5rem',
  },
  cardTitle: {
    fontSize: '1.1rem',
    fontWeight: 'bold',
    color: '#ffffff',
    margin: '0 0 4px 0',
  },
  cardDetail: {
    fontSize: '1rem',
    color: '#a0aec0',
    margin: 0,
  },
  // Form styles (copied from your previous component)
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '20px',
  },
  input: {
    backgroundColor: '#2d3748',
    color: '#e2e8f0',
    border: '1px solid #4a5568',
    borderRadius: '8px',
    padding: '16px',
    fontSize: '1rem',
    outline: 'none',
    transition: 'border-color 0.3s ease',
  },
  textarea: {
    backgroundColor: '#2d3748',
    color: '#e2e8f0',
    border: '1px solid #4a5568',
    borderRadius: '8px',
    padding: '16px',
    fontSize: '1rem',
    fontFamily: 'sans-serif',
    resize: 'vertical',
    minHeight: '120px',
    outline: 'none',
    transition: 'border-color 0.3s ease',
  },
  button: {
    backgroundColor: '#a7ffeb',
    color: '#1a202c',
    border: 'none',
    borderRadius: '12px',
    padding: '16px',
    fontSize: '1rem',
    fontWeight: 'bold',
    cursor: 'pointer',
    marginTop: '16px',
    transition: 'opacity 0.3s ease',
  },
};

// --- Combined Contact Section Component ---
const ContactSection = () => {
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Thank you, ${formData.name}. Your message has been received!`);
    setFormData({ name: '', email: '', message: '' });
  };

  return (
    <section id="contact" style={styles.contactSection}>
      <div style={styles.container}>
        {/* Left Column: Contact Info */}
        <div style={styles.infoColumn}>
          <h2 style={styles.title}>Let's Talk About Your Needs</h2>
          <p style={styles.subtitle}>
            Our team is ready to help. Reach out and we'll get back to you within 24 hours.
          </p>
          <div style={styles.cardsContainer}>
            {/* Email Card */}
            <a href="mailto:your.email@example.com" style={styles.card}>
              <div style={styles.iconWrapper}><FaEnvelope /></div>
              <div>
                <h3 style={styles.cardTitle}>Email Us</h3>
                <p style={styles.cardDetail}>your.email@example.com</p>
              </div>
            </a>
            {/* Phone Card */}
            <a href="tel:+911234567890" style={styles.card}>
              <div style={styles.iconWrapper}><FaPhoneAlt /></div>
              <div>
                <h3 style={styles.cardTitle}>Call Us</h3>
                <p style={styles.cardDetail}>+91 12345 67890 (9AM - 7PM IST)</p>
              </div>
            </a>
          </div>
        </div>

      </div>
    </section>
  );
};

export default ContactSection;
